create table if not exists projects(id uuid primary key default gen_random_uuid(),project_number text not null unique,estimate_id uuid not null references estimates(id),proposal_id uuid not null references proposals(id),accepted_revision_id uuid not null references proposal_revisions(id),acceptance_id uuid not null references proposal_acceptances(id),customer_id uuid not null references estimate_customers(id),property_id uuid not null references estimate_properties(id),signed_document_id uuid references proposal_documents(id),accepted_integrity_hash text not null,project_title text not null,accepted_contract_number text not null,accepted_revision_number integer not null,original_subtotal numeric not null,original_gst numeric not null,original_total numeric not null,current_subtotal numeric not null,current_gst numeric not null,current_total numeric not null,status text not null default 'accepted' check(status in('accepted','pre_production','awaiting_measurements','awaiting_product_selection','awaiting_colour_confirmation','awaiting_material_order','materials_ordered','scheduled','in_progress','substantially_complete','deficiency','complete','on_hold','cancelled','archived')),assigned_project_manager text,assigned_estimator text,target_start_date date,scheduled_start_date date,target_completion_date date,actual_completion_date date,crew text,subcontractor text,supplier text,permit_status text,material_order_status text,colour_confirmation_status text,customer_contact_status text,internal_notes text,production_notes text,change_order_sequence integer not null default 0,created_by text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,unique(acceptance_id));
create table if not exists project_status_history(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),previous_status text,new_status text not null,changed_by text not null,changed_at timestamptz not null default now(),note text);
create table if not exists project_operational_details(project_id uuid primary key references projects(id),confirmed_products jsonb not null default '[]',material_quantities jsonb not null default '[]',supplier_quote_number text,purchase_order_reference text,order_date date,expected_delivery date,actual_delivery date,delivery_location text,site_contact text,access_instructions text,safety_notes text,permit_information text,warranty_registration_status text,cleanup_requirements text,disposal_requirements text,special_instructions text,updated_by text,updated_at timestamptz not null default now());
create table if not exists project_colour_confirmations(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),scope text not null,product text not null,accepted_colour text,confirmed_colour text,status text not null check(status in('accepted_in_proposal','customer_confirmation_required','confirmed','changed_by_approved_change_order','supplier_confirmation_required','unavailable','substitute_proposed')),confirmation_source text,confirmed_by text,confirmed_at timestamptz,note text,no_cost_customer_confirmation jsonb,approved_change_order_revision_id uuid,created_at timestamptz not null default now(),check(coalesce(confirmed_colour,'')=coalesce(accepted_colour,'') or approved_change_order_revision_id is not null or no_cost_customer_confirmation is not null));
create table if not exists project_documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),document_type text not null,filename text not null,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=26214400),storage_path text not null unique,customer_shared boolean not null default false,uploaded_by text not null,created_at timestamptz not null default now());
create table if not exists project_image_associations(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),project_image_id uuid not null references project_images(id),category text not null check(category in('estimate','existing_condition','approved_scope','production','progress','deficiency','completion','warranty','change_order')),created_at timestamptz not null default now(),unique(project_id,project_image_id,category));
create table if not exists change_orders(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),accepted_proposal_id uuid not null references proposals(id),accepted_revision_id uuid not null references proposal_revisions(id),customer_id uuid not null references estimate_customers(id),property_id uuid not null references estimate_properties(id),sequence_number integer not null,change_order_number text not null,current_revision integer not null default 1,created_by text not null,created_at timestamptz not null default now(),unique(project_id,sequence_number),unique(project_id,change_order_number));
create table if not exists change_order_revisions(id uuid primary key default gen_random_uuid(),change_order_id uuid not null references change_orders(id),revision_number integer not null,status text not null default 'draft' check(status in('draft','internal_review','ready_to_send','sent','viewed','approved','declined','expired','voided','superseded')),title text not null,reason text not null,requested_by text,requested_date date,affected_scope text,existing_scope text,proposed_change text,change_type text not null,product_changes jsonb not null default '[]',colour_changes jsonb not null default '[]',schedule_impact jsonb not null default '{}',warranty_impact text,exclusions jsonb not null default '[]',assumptions jsonb not null default '[]',customer_notes text,internal_notes text,subtotal numeric not null default 0,gst numeric not null default 0,total numeric not null default 0,expiry_date date,allow_decline boolean not null default true,snapshot jsonb not null default '{}',pdf_storage_path text,signed_pdf_storage_path text,integrity_hash text,created_by text not null,created_at timestamptz not null default now(),locked_at timestamptz,unique(change_order_id,revision_number));
create table if not exists change_order_line_items(id uuid primary key default gen_random_uuid(),revision_id uuid not null references change_order_revisions(id),title text not null,description text,quantity numeric not null check(quantity>=0),unit text not null,unit_price numeric not null check(unit_price>=0),extension numeric not null,line_type text not null check(line_type in('addition','deduction','no_cost','allowance_reconciliation','unit_rate','tax_adjustment','custom')),linked_scope text,catalogue_item_id uuid,rate_item_id uuid,accepted_unit_rate numeric,customer_visible boolean not null default true,display_order integer not null,material_cost numeric,labour_cost numeric,overhead numeric,pricing_strategy jsonb,calculation_trace jsonb,check(line_type<>'unit_rate' or accepted_unit_rate is null or unit_price=accepted_unit_rate));
create table if not exists change_order_access_tokens(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),change_order_id uuid not null references change_orders(id),revision_id uuid not null references change_order_revisions(id),token_hash text not null unique check(length(token_hash)=64),expires_at timestamptz not null,revoked_at timestamptz,consumed_at timestamptz,first_viewed_at timestamptz,last_viewed_at timestamptz,created_by text not null,created_at timestamptz not null default now());
create table if not exists change_order_acceptances(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),change_order_id uuid not null references change_orders(id),revision_id uuid not null references change_order_revisions(id),token_id uuid not null references change_order_access_tokens(id),decision text not null check(decision in('approved','declined')),signer_name text not null,signer_title text,signer_email text not null,signature_type text check(signature_type in('typed','drawn')),signature_data text,customer_note text,subtotal numeric not null,gst numeric not null,total numeric not null,accepted_at timestamptz not null,request_ip_hash text,user_agent text,integrity_hash text not null,signed_pdf_storage_path text,created_at timestamptz not null default now(),unique(revision_id),unique(token_id));
create table if not exists change_order_documents(id uuid primary key default gen_random_uuid(),revision_id uuid not null references change_order_revisions(id),filename text not null,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=26214400),storage_path text not null unique,customer_visible boolean not null default false,created_by text not null,created_at timestamptz not null default now());
create table if not exists change_order_events(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),change_order_id uuid,revised_id uuid,event_type text not null,actor_type text not null check(actor_type in('admin','customer','system')),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists project_total_snapshots(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id),original_subtotal numeric not null,approved_change_order_subtotal numeric not null,current_subtotal numeric not null,current_gst numeric not null,current_total numeric not null,reason text not null,created_at timestamptz not null default now());
create index if not exists projects_estimate_idx on projects(estimate_id);create index if not exists projects_status_idx on projects(status,updated_at desc);create index if not exists change_orders_project_idx on change_orders(project_id,sequence_number);create index if not exists change_order_revisions_status_idx on change_order_revisions(status,created_at);create index if not exists change_order_tokens_hash_idx on change_order_access_tokens(token_hash);create index if not exists project_history_idx on project_status_history(project_id,changed_at);
create or replace function create_project_from_acceptance(p_acceptance uuid,p_actor text)returns uuid language plpgsql security definer set search_path=public as $$declare a proposal_acceptances%rowtype;p proposals%rowtype;e estimates%rowtype;v uuid;doc uuid;begin select * into a from proposal_acceptances where id=p_acceptance;select * into p from proposals where id=a.proposal_id and status='accepted';select * into e from estimates where id=p.estimate_id;if not found then raise exception 'accepted proposal unavailable';end if;select id into v from projects where acceptance_id=a.id;if v is not null then return v;end if;select id into doc from proposal_documents where proposal_id=p.id and revision_number=a.proposal_revision and document_type='signed' and status='completed' order by generated_at desc limit 1;insert into projects(project_number,estimate_id,proposal_id,accepted_revision_id,acceptance_id,customer_id,property_id,signed_document_id,accepted_integrity_hash,project_title,accepted_contract_number,accepted_revision_number,original_subtotal,original_gst,original_total,current_subtotal,current_gst,current_total,created_by)select 'PRJ-'||to_char(now(),'YYYY')||'-'||lpad(nextval('projects_project_number_seq')::text,5,'0'),p.estimate_id,p.id,a.revision_id,a.id,e.customer_id,e.property_id,doc,a.integrity_hash,p.proposal_number,p.proposal_number,a.proposal_revision,a.subtotal,a.gst,a.total,a.subtotal,a.gst,a.total,p_actor returning id into v;insert into project_status_history(project_id,new_status,changed_by,note)values(v,'accepted',p_actor,'Created from accepted proposal');insert into project_total_snapshots(project_id,original_subtotal,approved_change_order_subtotal,current_subtotal,current_gst,current_total,reason)values(v,a.subtotal,0,a.subtotal,a.gst,a.total,'project_created');return v;exception when unique_violation then select id into v from projects where acceptance_id=p_acceptance;return v;end$$;
create sequence if not exists projects_project_number_seq;
create or replace function next_change_order_number(p_project uuid,p_actor text)returns table(change_order_id uuid,change_order_number text)language plpgsql security definer set search_path=public as $$declare n integer;pr projects%rowtype;begin select * into pr from projects where id=p_project for update;if not found then raise exception 'project unavailable';end if;n:=pr.change_order_sequence+1;update projects set change_order_sequence=n,updated_at=now() where id=p_project;return query insert into change_orders(project_id,accepted_proposal_id,accepted_revision_id,customer_id,property_id,sequence_number,change_order_number,created_by)values(pr.id,pr.proposal_id,pr.accepted_revision_id,pr.customer_id,pr.property_id,n,'CO-'||lpad(n::text,3,'0'),p_actor)returning id,change_orders.change_order_number;end$$;
create or replace function refresh_project_totals(p_project uuid,p_reason text)returns void language plpgsql security definer set search_path=public as $$declare p projects%rowtype;delta numeric;begin select * into p from projects where id=p_project for update;select coalesce(sum(r.subtotal),0) into delta from change_order_revisions r join change_orders c on c.id=r.change_order_id where c.project_id=p_project and r.status='approved';update projects set current_subtotal=p.original_subtotal+delta,current_gst=round((p.original_subtotal+delta)*.05,2),current_total=round((p.original_subtotal+delta)*1.05,2),updated_at=now() where id=p_project;insert into project_total_snapshots(project_id,original_subtotal,approved_change_order_subtotal,current_subtotal,current_gst,current_total,reason)values(p_project,p.original_subtotal,delta,p.original_subtotal+delta,round((p.original_subtotal+delta)*.05,2),round((p.original_subtotal+delta)*1.05,2),p_reason);end$$;
create or replace function approve_change_order(p_token uuid,p_revision uuid,p_decision text,p_signer text,p_title text,p_email text,p_signature_type text,p_signature_data text,p_note text,p_subtotal numeric,p_gst numeric,p_total numeric,p_at timestamptz,p_ip_hash text,p_user_agent text,p_integrity text)returns uuid language plpgsql security definer set search_path=public as $$declare t change_order_access_tokens%rowtype;r change_order_revisions%rowtype;c change_orders%rowtype;v uuid;begin select * into t from change_order_access_tokens where id=p_token and revision_id=p_revision and revoked_at is null and consumed_at is null and expires_at>now() for update;if not found then raise exception 'token unavailable';end if;select * into r from change_order_revisions where id=p_revision and status in('sent','viewed') for update;select * into c from change_orders where id=r.change_order_id;if r.subtotal<>p_subtotal or r.gst<>p_gst or r.total<>p_total then raise exception 'totals changed';end if;if p_decision='declined' and not r.allow_decline then raise exception 'decline unavailable';end if;insert into change_order_acceptances(project_id,change_order_id,revision_id,token_id,decision,signer_name,signer_title,signer_email,signature_type,signature_data,customer_note,subtotal,gst,total,accepted_at,request_ip_hash,user_agent,integrity_hash)values(c.project_id,c.id,r.id,t.id,p_decision,p_signer,p_title,p_email,p_signature_type,p_signature_data,p_note,p_subtotal,p_gst,p_total,p_at,p_ip_hash,p_user_agent,p_integrity)returning id into v;update change_order_access_tokens set consumed_at=now() where id=t.id;update change_order_revisions set status=case when p_decision='approved'then'approved'else'declined'end,integrity_hash=p_integrity,locked_at=now() where id=r.id;if p_decision='approved'then perform refresh_project_totals(c.project_id,'change_order_approved');end if;insert into change_order_events(project_id,change_order_id,revised_id,event_type,actor_type,metadata)values(c.project_id,c.id,r.id,p_decision,'customer',jsonb_build_object('acceptance_id',v));return v;end$$;
create or replace function prevent_locked_change_order_update()returns trigger language plpgsql as $$begin if tg_op='DELETE'and old.status not in('draft','internal_review')then raise exception 'locked change-order revision is immutable';end if;if tg_op='UPDATE'and old.status not in('draft','internal_review')and (to_jsonb(new)-array['status','signed_pdf_storage_path','integrity_hash'])<>(to_jsonb(old)-array['status','signed_pdf_storage_path','integrity_hash'])then raise exception 'locked change-order revision is immutable';end if;return coalesce(new,old);end$$;drop trigger if exists immutable_change_order_revision on change_order_revisions;create trigger immutable_change_order_revision before update or delete on change_order_revisions for each row execute function prevent_locked_change_order_update();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('project-documents','project-documents',false,26214400,array['application/pdf','image/jpeg','image/png','image/webp','text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document'])on conflict(id)do nothing;
do $$declare t text;begin foreach t in array array['projects','project_status_history','project_operational_details','project_colour_confirmations','project_documents','project_image_associations','change_orders','change_order_revisions','change_order_line_items','change_order_access_tokens','change_order_acceptances','change_order_documents','change_order_events','project_total_snapshots']loop execute format('alter table %I enable row level security',t);execute format('create policy "project service role only" on %I for all using(auth.role()=''service_role'') with check(auth.role()=''service_role'')',t);end loop;end$$;
create policy "project document objects service only" on storage.objects for all using(bucket_id='project-documents' and auth.role()='service_role')with check(bucket_id='project-documents' and auth.role()='service_role');revoke all on function create_project_from_acceptance(uuid,text),next_change_order_number(uuid,text),approve_change_order(uuid,uuid,text,text,text,text,text,text,text,numeric,numeric,numeric,timestamptz,text,text,text)from public,anon,authenticated;grant execute on function create_project_from_acceptance(uuid,text),next_change_order_number(uuid,text),approve_change_order(uuid,uuid,text,text,text,text,text,text,text,numeric,numeric,numeric,timestamptz,text,text,text)to service_role;
alter table project_colour_confirmations add constraint project_colour_approved_change_fk foreign key(approved_change_order_revision_id) references change_order_revisions(id) on delete restrict;
